window.B2A_DICT_EXTRA={"Pour l'analyse photo par IA, activez votre code d'accès B2A ci-dessus.": {"en": "For AI photo analysis, activate your B2A access code above.", "it": "Per l'analisi foto con l'IA, attiva il tuo codice di accesso B2A qui sopra.", "es": "Para el análisis de fotos con IA, active su código de acceso B2A arriba."}, "Connexion au service IA…": {"en": "Connecting to the AI service…", "it": "Connessione al servizio IA…", "es": "Conectando con el servicio de IA…"}, "L'analyse par IA demande un code d'accès B2A (onglet Photo IA).": {"en": "AI analysis requires a B2A access code (Photo AI tab).", "it": "L'analisi con l'IA richiede un codice di accesso B2A (scheda Foto IA).", "es": "El análisis con IA requiere un código de acceso B2A (pestaña Foto IA)."}, "Code d'accès refusé. Vérifiez votre code dans l'onglet Photo IA.": {"en": "Access code refused. Check your code in the Photo AI tab.", "it": "Codice di accesso rifiutato. Verifica il codice nella scheda Foto IA.", "es": "Código de acceso rechazado. Verifique su código en la pestaña Foto IA."}, "L'IA n'a pas pu analyser cette photo. Essayez une autre image.": {"en": "The AI could not analyse this photo. Try another image.", "it": "L'IA non è riuscita ad analizzare questa foto. Prova un'altra immagine.", "es": "La IA no pudo analizar esta foto. Pruebe con otra imagen."}, "Vérifiez votre code d'accès.": {"en": "Check your access code.", "it": "Verifica il tuo codice di accesso.", "es": "Verifique su código de acceso."}, "Analyse et prévisions par l'IA": {"en": "AI analysis and forecasts", "it": "Analisi e previsioni con l'IA", "es": "Análisis y previsiones con IA"}, "L'IA étudie vos chiffres et vous donne une prévision sur {0} mois, les risques et les actions pour gagner plus.": {"en": "The AI studies your figures and gives you a {0}-month forecast, the risks and actions to earn more.", "it": "L'IA studia i tuoi numeri e ti dà una previsione a {0} mesi, i rischi e le azioni per guadagnare di più.", "es": "La IA estudia sus cifras y le da una previsión a {0} meses, los riesgos y las acciones para ganar más."}};
